head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > removeCellClass]<br/>Body Cell 정보를 사용하여 특정 Body Cell 에 설정된 CSS 클래스를 제거합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 CSS 클래스를 제거할 Body Cell 의 Row 인덱스를 설정합니다. (0부터, 표시된 Row 기준)",
        "columnInfo(필수) 파라미터로 CSS 클래스를 제거할 Body Cell 의 Column 인덱스를 설정합니다. (인덱스 0부터, 숨겨진 Column 도 포함)",
        "className(필수) 파라미터로 Body Cell 에서 제거할 CSS 클래스 이름을 공백으로 구분하여 설정합니다.",
        "removeCellClass() 실행 시 Body Cell 의 td 요소에 설정된 CSS 클래스가 제거됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="Column 인덱스 1 (col2) 은 숨김 처리되어 있으며, 숨겨진 Column 도 인덱스에 포함됩니다."', '', 'label1');

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (기본 4행)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (Body Column 인덱스: col1(0) ~ col4(3))
    await $c.gcm.createBasicGridView(cList);

    // Column 인덱스 1 (col2) 숨김 처리
    target1.setColumnVisible(1, false);
}



scwin.btn_setCellClass_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());

    // removeCellClass 검증 준비용으로 선택한 셀에 CSS 클래스('cRed cBlue') 설정
    target1.setCellClass(rowIndex, columnInfo, "cRed cBlue");
    wf_body_bottom.getObj("scwin").setReturnValue("setCellClass(" + rowIndex + ", " + columnInfo + ", cRed cBlue) 실행 (제거 검증 준비)");

    // 설정 직후 getCellClass 로 적용된 클래스 확인 (제거 전 상태)
    let rtn = target1.getCellClass(rowIndex, columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellClass(" + rowIndex + ", " + columnInfo + ") : " + rtn);
}



scwin.btn_removeCellClass_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());
    let className = par_className.getValue();

    // Column 인덱스로 Body Cell 에 설정된 CSS 클래스 제거 (공백 구분 복수 제거 가능)
    target1.removeCellClass(rowIndex, columnInfo, className);
    wf_body_bottom.getObj("scwin").setReturnValue("removeCellClass(" + rowIndex + ", " + columnInfo + ", " + className + ") 실행");

    // 제거 결과 확인 : removeCellClass 실행 시 getCellClass 는 (부분/전체 제거 무관) undefined 반환(저장값 초기화). 실제 남은 클래스는 아래 td className 으로 확인
    let rtn = target1.getCellClass(rowIndex, columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellClass(" + rowIndex + ", " + columnInfo + ") : " + rtn);

    // removeCellClass() 실행 시 td 요소에서 CSS 클래스가 제거되는지 확인 (공백 구분 복수 제거 시 일부만 남는지도 확인)
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + columnInfo + "']");
    wf_body_bottom.getObj("scwin").setReturnValue("td className : " + cellEl.className);
}
